uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Parameter mappings
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform float u_color_cycle;
uniform float u_layers;
uniform float u_mood; // Now acts as a continuous smooth color shifter!

out vec4 fragColor;

// --- Helper Functions ---

// 2D Rotation Matrix
mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// Simplex Noise Permutation
vec3 permute(vec3 x) { 
    return mod(((x * 34.0) + 1.0) * x, 289.0); 
}

// 2D Simplex Noise (Flawless organic noise)
float snoise(vec2 v) {
    const vec4 C = vec4(0.211324865405187, 0.366025403784439,
                       -0.577350269189626, 0.024390243902439);
    vec2 i  = floor(v + dot(v, C.yy));
    vec2 x0 = v - i + dot(i, C.xx);
    vec2 i1;
    i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    vec4 x12 = x0.xyxy + C.xxzz;
    x12.xy -= i1;
    i = mod(i, 289.0);
    vec3 p = permute(permute(i.y + vec3(0.0, i1.y, 1.0))
           + i.x + vec3(0.0, i1.x, 1.0));
    vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy),
             dot(x12.zw,x12.zw)), 0.0);
    m = m * m;
    m = m * m;
    vec3 x = 2.0 * fract(p * C.www) - 1.0;
    vec3 h = abs(x) - 0.5;
    vec3 ox = floor(x + 0.5);
    vec3 a0 = x - ox;
    m *= 1.79284291400159 - 0.85373472095314 * (a0*a0 + h*h);
    vec3 g;
    g.x  = a0.x  * x0.x  + h.x  * x0.y;
    g.yz = a0.yz * x12.xz + h.yz * x12.yw;
    return (130.0 * dot(m, g)) * 0.5 + 0.5;
}

// Fractal Brownian Motion
float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    mat2 shift = mat2(0.866, -0.5, 0.5, 0.866); 
    for (int i = 0; i < 4; i++) {
        v += a * snoise(p);
        p = shift * p * 2.0;
        a *= 0.5;
    }
    return v;
}

// Continuous Infinite Calm Palette
// u_mood offsets the phase, allowing infinite color combinations
vec3 palette(float t, float moodShift) {
    vec3 a = vec3(0.50, 0.50, 0.50); // Balanced brightness
    vec3 b = vec3(0.45, 0.40, 0.35); // Gentle, warm contrast
    vec3 c = vec3(1.00, 1.00, 1.00); 

    // moodShift is added directly to the math here. 
    // Moving the slider smoothly pushes the colors around the wheel!
    vec3 d = vec3(0.00, 0.33, 0.67) + moodShift; 

    return a + b * cos(6.28318 * (c * t + d));
}

// Healing Neural Fog
float getHealingFog(vec2 uv, float t) {
    vec2 driftUV = uv * 3.0 + vec2(t * 0.1, t * -0.05);
    float n = fbm(driftUV);
    return smoothstep(0.5, 0.85, n);
}

void main() {
    // 1. Correct Aspect Ratio UVs
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;

    // 2. Timing
    float spd = (u_speed <= 0.0) ? 0.15 : u_speed * 0.5;
    float t = iTime * spd;

    // We use u_mood directly as a float. 
    // Default fallback to 0.0 if not initialized.
    float currentMood = (u_mood <= -10.0) ? 0.0 : u_mood;

    // --- Dynamic Background tied directly to the Mood slider ---
    // By passing 'currentMood' into the palette, the background smoothly 
    // changes color to match the soundwaves perfectly.
    vec3 bgTop = palette(0.4, currentMood) * 0.35; // Darkened for contrast
    vec3 bgBottom = palette(0.8, currentMood + 0.1) * 0.15; // Deeper and shifted

    // Delta pulse applied to the background atmosphere
    float deltaPulse = sin(iTime * 2.0 * spd) * 0.05; 
    bgTop += deltaPulse; 

    vec3 finalColor = mix(bgBottom, bgTop, uv0.y + 0.5 + 0.1 * sin(t * 0.5));

    // Base fog highlight color (shifts with the mood, but pushed to a complementary hue)
    vec3 baseFogCol = palette(0.2, currentMood + 0.4); 

    // 3. Layer Loop
    float density = (u_layers <= 0.0) ? 4.0 : u_layers;
    float scale = (u_scale <= 0.0) ? 1.0 : u_scale;
    float brightness = (u_intensity <= 0.0) ? 1.5 : u_intensity;

    for(float i = 0.0; i < 6.0; i++) {
        if(i >= density) break;

        // --- Cymatic Soundwave Distortion ---
        vec2 waveUV = uv0 * (1.0 + scale * 0.3);
        waveUV *= rot(t * 0.05 + i * 1.2);

        float r = length(waveUV);
        float harmonic = sin(r * 12.0 - t * 3.0 + i) * 0.5;
        harmonic += cos(waveUV.x * 3.0 - t + i * 1.5) * 0.3;

        float dist = abs(harmonic - 0.1);

        // --- Intense Sonic Glow ---
        float coreGlow = exp(-dist * 14.0) * 0.8; 
        float softGlow = exp(-dist * 3.0) * 0.4; 

        // --- Healing Fog Logic ---
        vec2 fogUV = waveUV;
        fogUV.x += harmonic * 0.3; 

        float fogMap = getHealingFog(fogUV + vec2(i * 1.5, i * 2.5), t);

        float waveMask = exp(-dist * 1.5); 
        float fog = fogMap * waveMask * 2.0; 

        // 4. Coloring (Using the continuous mood shifter)
        float cycle = (u_color_cycle <= 0.0) ? 0.2 : u_color_cycle;
        vec3 col = palette(r * 0.3 + i * 0.2 + t * cycle, currentMood);

        // Dynamic fog color blend
        vec3 fogCol = mix(col, baseFogCol, 0.7);

        // Accumulate: Sonic Waves + Healing Fog
        finalColor += col * (coreGlow + softGlow) * brightness * 0.7;
        finalColor += fogCol * fog * brightness;
    }

    // 5. Post-Processing
    float vig = 1.0 - length(uv0) * 0.6;
    finalColor *= vig;

    // Smooth Tone Mapping
    finalColor = smoothstep(-0.05, 1.3, finalColor);

    fragColor = vec4(finalColor, 1.0);
}

